        self.username = username
        self.password = password
        self.exercises = []

class Exercise:
    def __init__(self, title, exercise_type, content, creator):
        self.id = str(uuid.uuid4())
        self.title = title
        self.exercise_type = exercise_type
        self.content = content
        self.creator = creator
        self.reviews = []

users = {
    'testuser': 'password123'
}

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        if username in users and users[username] == password:
            session['username'] = username
            return redirect(url_for('home'))
        return 'Invalid credentials', 401
    return render_template('login.html')

@app.route('/create_exercise', methods=['GET', 'POST'])
def create_exercise():
    if 'username' not in session:
        return redirect(url_for('login'))
    if request.method == 'POST':
        title = request.form['title']
        exercise_type = request.form['exercise_type']
        content = request.form['content']
        new_exercise = Exercise(title, exercise_type, content, session['username'])
        # Add to current user's exercises
        # In a real app, we'd have a user database to store exercises
        current_user = User(session['username'], None)
        current_user.exercises.append(new_exercise)
        return redirect(url_for('home'))
    return render_template('create_exercise.html')

@app.route('/share_exercise/<exercise_id>')
def share_exercise(exercise_id):
    return f"Sharing exercise {exercise_id}"

@app.route('/review_exercise/<exercise_id>', methods=['GET', 'POST'])
def review_exercise(exercise_id):
    if 'username' not in session:
        return redirect(url_for('login'))
    if request.method == 'POST':
        feedback = request.form['feedback']
        # In a real app, we'd retrieve the exercise and add the review
        return jsonify({'status': 'success', 'message': 'Review submitted'})
    return render_template('review_exercise.html', exercise_id=exercise_id)

# Test cases (for framework)
def test_user_creation():
    user = User("test", "password")
    assert user.username == "test"

def test_exercise_creation():
    exercise = Exercise("Test", "quiz", "Question", "testuser")
    assert exercise.title == "Test"

if __name__ == '__main__':
    app.run(debug=True)
